{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C70"],
      "claim": "Isoniazid, a small heteroaromatic anti-infective, has an absolute oral bioavailability of 93% in fasting TB patients, supporting high F for the similarly small nitroimidazole amide query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Safinamide, a benzylamine-containing small molecule, has an absolute oral bioavailability of 95% in fasted healthy subjects, supporting high oral F for the benzylamide-containing query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Fenspiride, a small basic drug, has an absolute oral bioavailability of 90% in healthy volunteers, supporting high F for a small orally absorbed molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Pethidine, a small lipophilic basic drug, has an absolute oral bioavailability of 47–73% in healthy subjects, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C56"],
      "claim": "Labetalol, a structurally different aryl-ethanolamine with extensive first-pass metabolism, has a reported oral bioavailability of 18%, below the threshold; this is contradictory but weakly transferable because the query lacks labetalol's phenolic conjugation liability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a small nitroimidazole amide. High-F analogues (isoniazid 93%, safinamide 95%, fenspiride 90%, pethidine 47–73%, vorinostat 43%) overwhelmingly support F ≥ 20%; the only sub-threshold analogue, labetalol (18%), is structurally distant and outweighed. Prediction: high.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement for the query molecule.",
    "No nitroimidazole-containing analogue is present in the evidence set; the closest is isoniazid, a pyridine hydrazide."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

